// Rebuilds packages/contracts/src/generated/index.ts from the files ts-rs
// emitted (run `cargo test -p runmarq-core` first, or `pnpm contracts`).
import { readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const dir = join(dirname(fileURLToPath(import.meta.url)), "..", "packages", "contracts", "src", "generated");
const types = readdirSync(dir)
  .filter((f) => f.endsWith(".ts") && f !== "index.ts")
  .map((f) => f.slice(0, -3))
  .sort();

const body = [
  "// Generated by scripts/gen-contracts.mjs from Rust types (ts-rs). Do not edit.",
  ...types.map((t) => `export type { ${t} } from "./${t}";`),
  "",
].join("\n");
writeFileSync(join(dir, "index.ts"), body);
console.log(`contracts: ${types.length} types`);
